insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 1, 'OFON-1 is authorised at 27050000 USD and the engine forecasts 27600000 on the same lines. Which lines lift the forecast past the authorisation, and by what figure on each?', '["DRL-01 and CMP-05, the two largest budgets, because a forecast at completion grows with the size of the lines it adds and those two carry most of the AFE.", "LOG-04 and CMP-05, whose commitments of 900000 and 1200000 are added on top of their budgets once a contractor order has been placed against the line.", "CSG-02, which has already spent 4300000 against a budget of 3900000, and CMT-03, whose entered forecast of 1400000 stands over its budget of 1250000.", "DRL-01 and CSG-02, the two lines that have spent most of their budgets, since the forecast projects each line''s spend forward at its current rate."]'::jsonb, 2, 'The overrun of 550000 is 400000 on CSG-02 and 150000 on CMT-03; DRL-01''s 12400000 spent and committed is still under its 14200000, so it forecasts its budget.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 2, 'A cost report prints LOG-04 as 350000 spent of a 2100000 budget, a line that looks barely touched. What has the report left out?', '["The 900000 committed to contractors and not yet paid, so 1250000 of the line is already spoken for.", "The invoices billed against the line, which would lift its actual to the 4400000 dated 2027-06-05 once they are posted to it.", "Its entered forecast, which the engine substitutes for the budget on every line that has spent less than half of its authorisation.", "Its progress of 20.0000 percent, which turns the 350000 spent into 420000 of work and shows the line running ahead of its budget."]'::jsonb, 0, 'A commitment is money already promised through an order or contract; actual plus commitment on LOG-04 is 350000 + 900000 = 1250000 against the 2100000 budget.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 3, 'A contractor order on DRL-01 is paid and its amount is moved into the line''s actual, but nobody takes it out of the commitment. What happens?', '["The engine matches the paid amount against the commitment it came from and removes it, so the line''s forecast is unchanged by the move.", "The engine refuses the line once actual plus commitment passes the budget, and its message names the cost item carrying the excess.", "Nothing moves in any reading, because the forecast rule reads the budget and the entered forecast and never looks at the commitment column.", "Actual plus commitment counts the order twice, and the forecast rule can read the double count as an overrun without any check."]'::jsonb, 3, 'The commitment is a typed figure the engine never ties to a contract or an invoice; DRL-01 already carries 9800000 spent and 2600000 committed, 12400000, against 14200000.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 4, 'OFON-1 reads 55.7856 percent spent. What sits in the numerator of that figure?', '["Actuals and commitments together, because money promised to a contractor is money the AFE can no longer spend on anything else.", "Only the 15090000 of actuals on the lines; the 5000000 committed stays outside it.", "The earned value of 15231500, since percent spent measures how much of the authorised budget the finished work has used up.", "The invoice total, because a spend percentage is a reading of money that has left the company and only the invoices carry a date."]'::jsonb, 1, 'Percent spent is 15090000 over the budget of 27050000. CPI and percent spent read the line actuals only; commitments enter the forecast rule and nothing else.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 5, 'A fifth invoice is entered on OFON-1 and no line''s actual is changed. Which reading moves?', '["CPI and percent spent, which read spend, while the curve reads line actuals.", "The S-curve''s Actual series, while CPI, percent spent and the EAC stay where they were.", "The EAC, on the line the engine matches to the invoice by its amount.", "Every reading, since the engine reconciles invoices with line actuals."]'::jsonb, 1, 'The metrics read actuals from the cost lines and the S-curve reads the dated invoices; OFON-1''s four invoices and its line actuals both total 15090000 only by construction.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 6, 'An invoice on an AFE is saved with a null date. What does the engine as published do with it?', '["Refuses the AFE with an error naming the invoice, as for negative progress.", "Leaves it off the S-curve, since an undated invoice has no month to fall in.", "Places it at the as-of date, so it lifts only the points from then on.", "Counts it from 1970, so it appears in every bucket of the S-curve from the first point on."]'::jsonb, 3, 'The engine does not refuse an undated invoice; the null date counting from 1970 is a finding recorded and not repaired, so that amount lands at the start of every curve, while an invoice with no date field never counts.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 7, 'A reviewer sees 15090000 of actuals on the OFON-1 dashboard and 15090000 at the last Actual point of its S-curve. What has the reviewer established?', '["That two totals match, which says nothing about whether every invoice is dated or where each one''s money went.", "That every invoice was posted to the right line, since the curve sums invoices by cost code.", "That the line actuals are correct, because the curve is built from those same line actuals and could not reach the total otherwise.", "That the engine reconciled the two records, since it declines to draw a curve whose invoices disagree with the actuals on the lines."]'::jsonb, 0, 'The engine reconciles nothing: an invoice carries a date and an amount and no cost code, and on OFON-1 the 15090000 agreement holds by construction.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 8, 'OFON-1 carries an invoice of 5200000 dated 2027-04-10. Which cost line is it for?', '["DRL-01, the only line whose actual of 9800000 is large enough to hold it.", "Every line in proportion to its actual, as the engine spreads each invoice.", "The AFE cannot say, because an invoice carries a date and an amount and no cost code.", "CSG-02, since the engine books an invoice to the nearest line actual."]'::jsonb, 2, 'The line actuals say where the money went and the invoices say when; no OFON-1 invoice equals any line''s actual, and the 5200000 could be drilling, casing or both.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 9, 'Casing bought in another currency is to be entered on OFON-1, which is kept in USD. Where is the exchange rate held?', '["In a currency code held on each cost line, so every line converts at its own rate before the engine totals the budget of 27050000.", "In the partner split, which bills each partner in its own currency.", "Beside each invoice, so the S-curve can restate the casing spend in USD.", "Nowhere in the AFE: the amount is converted before it is typed, at a rate the engine never sees."]'::jsonb, 3, 'The AFE holds one currency code for its lines, invoices and partners and no exchange rate among its inputs; OFON-1''s 27050000 is whole USD as the engine prints it.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 10, 'A cost line is typed in a local currency beside four lines kept in USD. What does the engine do with it?', '["Adds it to the other lines without complaint, because it holds one currency code and has no way to know.", "Refuses the AFE, since a line whose amounts are out of scale with the rest fails the same input check that refuses negative progress.", "Flags the line and leaves it out of the EAC until an exchange rate is supplied.", "Converts it at the exchange rate stored with the AFE''s currency code."]'::jsonb, 0, 'Nothing in the engine can tell a local amount from a USD one, so the mixed ledger totals quietly, just as OFON-1''s lines total 27050000 in one currency.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 11, 'Why would OFON-1''s CPI of 1.009377 read the same if every amount on the AFE were restated in one other currency?', '["The engine converts every amount to USD before it forms a ratio, so the currency the lines are typed in never reaches the index.", "It is 15231500 over 15090000, one amount over another in the same currency, so the unit cancels.", "CPI is formed from the progress percents alone, which carry no currency.", "It would not, since CPI is quoted against USD and needs the rate applied."]'::jsonb, 1, 'Earned value over actuals divides like by like; percent spent 55.7856 and percent complete 56.3087 cancel the unit the same way.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 12, 'Someone rewrites OFON-1''s budget of 27050000 in millions, rounded, to lay it beside a capital portfolio figure in million USD. What is wrong?', '["Only the rounding, since at four decimals the budget would sit correctly in a portfolio sum.", "Only the scale, since the portfolio is kept in thousands of USD and the budget has to be divided by a thousand before it is added.", "The two models share nothing, and the rescaled figure is a number the engine never printed and nobody can check.", "Only the sign, since the portfolio records a capex as a negative figure and the budget has to be negated before the two are added."]'::jsonb, 2, 'OFON-1 is whole USD against line budgets and the portfolio is million USD with whole projects against a limit; a figure from one never belongs in a sum with the other.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 13, 'One cost line is saved with a progress of -0.5 percent and another with progress past 100 percent. What does the engine do?', '["Refuses the first with a message naming the cost item, and accepts the second, letting it earn more than its budget.", "Refuses both, since its own message says progress runs from 0 to 100 percent.", "Clamps both into the range, reading the first as 0 and the second as 100, and reports the clamped figures as though they were typed.", "Accepts both with a flag, leaving the flagged lines out of earned value while still carrying their budgets in the EAC and the total."]'::jsonb, 0, 'Negative progress stops the calculation with "Progress runs from 0 to 100 percent." in the message, yet progress past 100 is taken, and earned value is only as good as the progress typed in.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 14, 'OFON-1 is reported again on a later date with every line unchanged. Which of its four headline readings can change?', '["The EAC, since a forecast at completion is recomputed from the spend expected by the date of the report and moves with each one.", "CPI, since actuals are counted only up to the as-of date of the report.", "All four, since every figure the engine prints is a reading of one day.", "Only SPI, 0.872063 as of 2027-08-15; the EAC, earned value and CPI stay as the lines have them."]'::jsonb, 3, 'The EAC of 27600000, earned value of 15231500 and CPI of 1.009377 are read from the lines as entered; only the schedule reading depends on the as-of date.'),
  ('portfolio', 'intermediate', 'module', 'm01-an-afe-is-a-promise', 15, 'OFON-1 has spent 15090000. How much work has that money bought?', '["15090000 of work, since a dollar spent buys a dollar of scope.", "What the invoices cover, since an invoice follows delivered work.", "The spend cannot say; the typed progress says it, and on OFON-1 it earns 15231500.", "55.7856 percent of the scope, the share of the budget spent."]'::jsonb, 2, 'Spending and progress are separate columns: earned value is each budget times its typed progress, 15231500 on OFON-1, and actuals of 15090000 say only what was paid.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 1, 'CMT-03 has a budget of 1250000, has spent and committed 940000, and forecasts 1400000. What sets that forecast?', '["The larger of its budget and actual plus commitment, raised by a contingency the engine adds to every line still in progress.", "The positive forecast its engineer entered, which the rule takes ahead of both the budget and the spend.", "Its 640000 spent projected to completion at its progress of 55.0000 percent, which the rule switches to once a line is past half done.", "Its actual plus commitment of 940000, carried up by the overrun the line has already booked against its budget of 1250000."]'::jsonb, 1, 'Left to the fallback, CMT-03 would forecast its budget of 1250000; the entered 1400000 wins, so its variance of -150000 exists only because someone typed it.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 2, 'CMT-03''s entered forecast is replaced by 900000, below the 940000 already spent and committed on the line. What does the line forecast?', '["940000, because the engine floors an entered forecast at the money already spent and committed before it accepts the figure.", "1250000, because a forecast below the spend to date is not credible and the rule falls back to the larger of its two formula figures.", "Nothing, because a forecast below actual plus commitment is refused with an input error that names the cost item carrying it.", "900000, because any positive entered forecast is taken as typed."]'::jsonb, 3, 'The rule never compares a positive entry with the spend (finding EC5-1); an entry of 1 on the same line forecasts 1.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 3, 'CMP-05''s completion work is cancelled and its forecast field is set to 0. What does the OFON-1 report show?', '["No saving: the line still forecasts 5600000, the EAC stays 27600000 and the variance stays -550000.", "A saving of 5600000, because a zero forecast takes the line out of the EAC while its budget stays in the authorised total.", "An EAC that drops to take in only the 1200000 committed on the line, since a cancelled line still owes the orders already placed.", "A refusal naming CMP-05, since a forecast of 0 fails the input check in the same way that a negative progress figure does."]'::jsonb, 0, '0 is not positive, so the rule falls back to the larger of the 5600000 budget and the 1200000 spent and committed; a descope saves nothing until the budget itself is changed.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 4, 'DRL-01 has spent 9800000 and committed 2600000 on a budget of 14200000 and is 72.0000 percent complete, with no entered forecast. Why does it forecast 14200000?', '["The rule projects the 9800000 spent from 72.0000 percent complete, capped at budget.", "A line forecasts its budget until its progress reaches 100.0000 percent.", "The rule takes the larger of the budget and the 12400000 spent and committed, and the budget is larger.", "The engine divides the budget by the AFE''s CPI of 1.009377 and rounds the result back up to the budget, as the line is ahead."]'::jsonb, 2, 'The fallback reads money spent and promised and nothing else; it never reads progress or CPI, so DRL-01''s 72.0000 percent plays no part in its forecast.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 5, 'DRL-01, LOG-04 and CMP-05 each show a line variance of 0. What does that 0 establish?', '["Only that spend plus commitment has not yet passed the budget and nobody has entered a forecast.", "That the three lines are on budget, since each will finish at its authorisation.", "That the lines will save money, since the fallback rounds an underrun down to 0.", "That the three lines have not started, since only progress books a variance."]'::jsonb, 0, '0 is the rule''s floor: without an entered forecast a line''s forecast is at least its budget. DRL-01 is 72.0000 percent complete and still shows 0.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 6, 'With CMT-03''s other figures unchanged, an entered forecast of 1 makes it forecast 1, and an entered forecast of 0 makes it forecast 1250000. What separates them?', '["The engine reads 1 as a forecast stated in millions and scales it up before comparing, while it reads 0 as a field left blank.", "Only the sign test: 1 is positive and taken as typed, while 0 is not positive and falls back to the formula.", "A forecast of 1 is held for review and shown as entered, while a forecast of 0 is taken as a descope and the line keeps its budget.", "A floor at actual plus commitment applies only to a zero entry and leaves 1 alone."]'::jsonb, 1, 'Nothing checks a positive entry against the 940000 already spent and committed, so 1 stands; 0 falls to the larger of 1250000 and 940000.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 7, 'OFON-1''s variance at completion is -550000. How is it built?', '["Budget less actuals less commitments, the money the AFE has left to spend.", "The overrun on CSG-02 alone, with the AFE''s CPI of 1.009377 applied to the rest of the budget to project the lines not yet done.", "Actuals of 15090000 set against planned value on the report date, since a variance compares money spent with the calendar.", "Budget 27050000 less EAC 27600000, which is -400000 on CSG-02, -150000 on CMT-03 and 0 on the other lines."]'::jsonb, 3, 'Variance is budget less EAC, so an overrun is negative; the line variances add to the same -550000.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 8, '"suite test: entered forecast" has nothing spent or committed and forecasts 140.0000 on a budget of 100. What makes its overrun different from the 130.0000 in "suite test: committed past the budget"?', '["It is no overrun, since a variance is booked only once actuals are recorded.", "The engine leaves an entry with no spend out of the EAC until money is spent.", "Nothing, since both lines forecast the larger of budget and actual plus commitment.", "It rests on a typed judgment with nothing spent, while 130.0000 is money already spent and promised."]'::jsonb, 3, 'The first returns variance -40.0000 on an entry of 140 alone; the second has 70 spent and 60 committed, which pass the budget of 100 and give -30.0000.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 9, 'The published line "negative entered forecast is ignored (the S-curve ignores it too)" has a budget of 100, 20 spent and an entered forecast of -50. Why does it forecast 100.0000?', '["The engine refuses the -50 with a message naming the line and restores the budget, as it does for a negative progress figure.", "The -50 is booked as a saving, and the variance is then clamped at 0.0000.", "-50 is not positive, so the rule compares the budget of 100 with the 20 spent and takes the larger.", "The engine reads the minus sign as a typing slip and uses 50, then floors the forecast of that line at its budget of 100."]'::jsonb, 2, 'Ignored is not refused: nothing on the screen says the -50 was never used, and the line returns EAC 100.0000 and variance 0.0000.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 10, 'CMP-05 forecasts 5600000. Can a reviewer tell from that whether its forecast field is blank, 0 or negative?', '["No, since none of the three is positive and each falls back to the same 5600000 without a word.", "Yes, since a negative forecast is refused with a message and a blank is not.", "Yes, since a zero forecast drops the line from the EAC and a blank does not.", "Yes, since the rule used column prints entered for any figure typed into the forecast field, whatever the sign of that figure."]'::jsonb, 0, '"Not yet estimated", "cancel this work" and a typing slip produce one forecast: the larger of 5600000 and the 1200000 spent and committed.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 11, 'Had CSG-02''s budget of 3900000 been copied into its forecast field, as editing a line did before EC5-0, what would the line report?', '["4300000 and -400000, since entries are floored at the money spent.", "A refusal, since an entry below the actual of 4300000 is rejected.", "A forecast of 3900000 and a variance of 0, hiding the 400000 overrun already spent.", "4300000 and -400000, since a forecast equal to its budget is ignored."]'::jsonb, 2, 'A copied budget is a positive entered forecast and wins; the repaired Suite no longer copies it, but a figure copied by hand does the same damage.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 12, 'Before EC5-0 the Cost Breakdown table showed the budget as the forecast and the PDF and Excel variance was budget less actual. What does the repaired Suite show on OFON-1?', '["27050000 as the table''s forecast, since it shows what was authorised.", "27600000 and -550000 on the tiles, the table, both exports and the Top 5, all from the one rule.", "The one rule on screen, while the PDF and Excel exports keep budget less actual so that earlier issued reports still reconcile.", "27600000 on the tiles and table, while the Top 5 keeps its own old rule."]'::jsonb, 1, 'After the Suite repair the tiles, Cost Breakdown table, PDF, Excel and Top 5 read one rule, so a disagreement between two reports points at the data or the export date.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 13, 'Every repaired screen now reads the one forecast rule. What has that fixed, and what has it left alone?', '["It fixed the forecast, which now extrapolates from progress and CPI.", "Nothing, since every old screen already showed 27600000.", "It made the rule stricter, refusing a forecast below the spend.", "It makes the screens agree, and every screen still shares the rule''s limits."]'::jsonb, 3, 'No screen forecasts a line under its budget without an entered forecast, and none reads progress, CPI or a non-positive entry, so OFON-1''s EAC is still 27600000.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 14, 'A partner reads OFON-1''s EAC of 27600000 as a projection from performance to date. What is it?', '["The budget of 27050000 scaled up by the ratio of actuals to earned value across the lines, which is how cost performance is projected.", "14200000 + 4300000 + 1400000 + 2100000 + 5600000: three budgets, one spend and one entered figure, added.", "The actuals of 15090000 plus the remaining budget divided by CPI, the standard projection of cost to completion from performance.", "The 15090000 spent plus the 5000000 committed plus the budgets of unstarted lines."]'::jsonb, 1, 'The rule reads budgets, actual plus commitment and entered forecasts and never progress, so the EAC carries no reading of performance.'),
  ('portfolio', 'intermediate', 'module', 'm02-one-forecast-rule', 15, 'A line is half done and already past its budget on spend and commitment, with no entered forecast. What does the rule forecast for the half still to do?', '["Nothing, since it forecasts only what is spent and committed until someone enters a forecast.", "The rest of the budget at the line''s progress rate, since the rule extrapolates a line from its progress once spend passes the budget.", "Twice its spend and commitment, projected from its half-done progress.", "The whole budget again, as a line past its budget gets a fresh one."]'::jsonb, 0, 'The rule refuses to forecast what has not been committed; CSG-02 forecasts 4300000 because its spend passes its budget and nothing more is committed, and a half-done line past its budget would stop at its spend and commitment just the same, whatever its progress.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 1, 'OFON-1''s earned value is 15231500. How does the engine reach it?', '["The actuals of 15090000 scaled by CPI, which is how much work each dollar spent has bought across the AFE.", "The average of the five progress figures applied to the budget of 27050000 as a single percent complete.", "Each line''s actual times its progress, with the invoice total standing in for lines that have not reported.", "Each line''s budget times its progress, added: 10224000 + 3900000 + 687500 + 420000 + 0."]'::jsonb, 3, 'DRL-01 at 72.0000 percent of 14200000 earns 10224000; divided by the budget of 27050000 the sum gives percent complete 56.3087.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 2, 'A progress report averages OFON-1''s five progress figures to give the AFE''s percent complete. What is wrong with that?', '["Nothing, since a plain mean of five percents gives the same 56.3087 percent as weighting each line by its budget.", "It gives CMT-03''s 55.0000 percent on a 1250000 line the same vote as DRL-01''s 72.0000 percent on 14200000.", "It should weight each line by its actuals, since a line counts for what it has cost, and that gives the engine''s 56.3087.", "It double counts CSG-02, which is 100.0000 percent complete and should leave the average once the line has closed."]'::jsonb, 1, 'The engine weights by budget, so its 56.3087 percent is mostly a statement about drilling, which earns 10224000 of the 15231500.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 3, 'CSG-02 is 100.0000 percent complete, having spent 4300000 against a budget of 3900000. What does it earn?', '["4300000, what the finished line actually cost, since complete work earns whatever was paid to get it done.", "Its budget less its overrun, since earned value nets off any overspend on a line before it is added up.", "3900000, its budget, since earned value pays each line what its work was authorised to cost.", "The larger of its budget and its actual, the same choice the forecast rule makes on a line with no forecast."]'::jsonb, 2, 'The budget is the weight and never the actual, which is what makes earned value useful against spend: CSG-02 earns 3900000 and spent 4300000.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 4, '"progress beyond 100 percent earns beyond the budget" returns earned value 150.0000 against actuals of 90.0000 and CPI 1.666667. What does that CPI record?', '["Progress typed past 100 percent, which the engine accepts and which earns beyond the budget without a dollar saved.", "A genuine saving, since 150.0000 over 90.0000 is exact arithmetic on the line''s own earned value and actuals.", "A clamp, since the engine caps progress at 100 percent and 1.666667 is the index it reports at that cap.", "An inverted index, actuals over earned value, which the engine switches to once progress passes 100 percent."]'::jsonb, 0, 'The refusal message says progress runs from 0 to 100 percent, yet only negative progress is refused; the same case reports SPI 1.500000 from the same typing.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 5, 'CMP-05 is typed at 100.0000 percent complete with an actual of 0. What does it earn?', '["Nothing, since earned value on a line is capped at the money that has actually been spent on that line so far.", "Nothing, since the engine refuses a line claiming complete work with no spend and names CMP-05 in its message.", "Its commitment of 1200000, since a line with no actuals earns only against the contractor orders already placed.", "Its whole budget of 5600000, since the engine multiplies typed progress by budget and never checks it against spend."]'::jsonb, 3, 'The engine does not measure metres drilled or stages completed; it reads a percentage and multiplies, so earned value is only as good as the progress typed in.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 6, 'OFON-1 reports CPI 1.009377 and a variance at completion of -550000 on the same day. How can both be true?', '["One of them is stale, since CPI is taken at the as-of date and the variance at completion is taken at the window end.", "CPI above 1 means the overrun will be recovered by completion, so the variance is a figure that closes to 0 as work finishes.", "They read different columns: CPI reads progress and actuals, the forecast rule reads budgets, spend, commitment and entries.", "The variance counts the 5000000 committed and CPI does not yet, so the two agree once the open orders are paid."]'::jsonb, 2, 'CMT-03 shows it plainly: it has earned 687500 for 640000 spent and still forecasts 1400000 against 1250000 because an engineer entered that figure.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 7, '"suite test: weighted earned value" reports CPI 1.000000 with 110.0000 earned and nothing spent. How should that CPI be read?', '["As work bought at exactly its budget, one for one.", "As undefined: with actuals of 0 the engine returns 1 whatever has been earned.", "As infinity clamped to 1, the largest index the engine reports.", "As a null that the screens print as 1.000000 in place of a blank."]'::jsonb, 1, 'CPI 1 before any spend is a finding left unrepaired; the same case reports SPI 0.275000, a real ratio of earned value to planned value, beside a CPI that is only a default.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 8, '"suite test: empty AFE" has nothing budgeted, earned or spent and returns CPI 1.000000 and SPI 1.000000. Where does each 1 come from?', '["Both are measurements: an empty AFE has done all its scope, on budget and on time.", "CPI from the default for zero actuals, and SPI from a zero-budget guard that fires before the null rule.", "Both come from the zero-actuals default, which the engine applies to every index once nothing at all has been spent.", "SPI from time progress falling back to 1 on an AFE without dates, and CPI from 0 over 0 being read as exactly 1."]'::jsonb, 1, 'Where planned value is zero SPI is null, except that an AFE whose budget is 0 reports SPI 1 because its guard is checked first; neither 1 is a reading of performance.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 9, 'As of 2027-08-15 OFON-1''s planned value is 17466060. What is that figure?', '["The budget of 27050000 times 0.645695, the share of the window''s whole days elapsed by that date.", "What OFON-1 should have spent by then under its front-loaded drilling plan.", "The total of the invoices dated on or before 2027-08-15, which is the spend the calendar can see by the date of the report.", "The budget times percent complete, the work credited by that date."]'::jsonb, 0, 'The plan is a straight line from 0 on 2027-02-01 to the whole budget on 2027-11-30: 195 of 302 days have passed, and the engine has no rig schedule to bend it.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 10, 'OFON-1 reads SPI 1.141290 in one report and 0.872063 in another on identical lines. What separates them?', '["Progress typed between the two reports, which lifted earned value ahead of the plan in June and let it fall back by August.", "The invoice dated 2027-07-18, which raised the actuals between the two dates and pulled the schedule index down with them.", "CPI moving from ahead to behind between the two dates, which SPI inherits because it divides by the cost index.", "The as-of date: planned value is 13345861 at 2027-06-30 and 17466060 at 2027-08-15 against earned value of 15231500."]'::jsonb, 3, 'Earned value does not move with the date and planned value does, so the same lines read ahead at 1.141290 and behind at 0.872063.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 11, 'As of 2027-02-01, the start day, OFON-1 has already earned 15231500 by its figures. What SPI does the engine report?', '["1, since a zero denominator gives 1, as CPI does before any spend.", "0.563087, since time progress falls back to 1 when no day has elapsed.", "Null, since no whole day has elapsed, planned value is 0 and there is nothing to divide by.", "Infinity, earned value over a planned value of 0, far ahead of schedule."]'::jsonb, 2, 'SPI is null before the start and on the start day; before EC5-0 the engine reported Infinity before the start date when value had been earned, and a report that prints the null as 0 or 1 has made one up.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 12, 'From 2027-11-30 onward OFON-1''s SPI reads 0.563087. Why that figure?', '["The engine freezes SPI at its last reading inside the window once the as-of date passes the end of that window.", "SPI is scaled down by the days of delay counted since 2027-11-30.", "The plan runs on past the end, so planned value grows beyond 27050000.", "Planned value has reached the whole budget, so SPI is percent complete, 56.3087, divided by 100."]'::jsonb, 3, 'Time progress stops at 1.000000, so 2028-01-10 reads 15231500 over 27050000 exactly as the end day does.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 13, 'OFON-1''s lines, saved through the pre-EC5-0 wizard that took no window dates, are reported on 2027-06-30. Which SPI does that old report print?', '["Null on every day, since with no window the engine could not form a planned value and declined to divide.", "0.563087, percent complete over 100, because time progress fell back to 1 on every day of the AFE''s life.", "1.141290, since the engine took the first invoice date, 2027-02-20, as the start of the missing window.", "0.872063, since the engine read the clock and applied the fallback only to the days before any start date."]'::jsonb, 1, 'The published "no dates: time progress 1" case still records the fallback; with the whole budget planned every day, SPI said nothing about the calendar.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 14, 'OFON-1 reads 55.7856 percent spent and 56.3087 percent complete. What does the pair show?', '["Their ratio is CPI 1.009377, because they share the budget; neither says which lines are over budget.", "That OFON-1 is 55.7856 percent done, the scope the money has delivered.", "That OFON-1 is on schedule, since percent complete running ahead of percent spent is what an SPI above 1 means.", "That no line is over budget, or complete would sit below spent."]'::jsonb, 0, 'Percent spent is actuals over budget and percent complete is earned value over budget, so the budget cancels; CSG-02 finished over its line inside that matched pair.'),
  ('portfolio', 'intermediate', 'module', 'm03-earned-value', 15, 'SPI sets budget-weighted progress against a straight-line plan across the window. What does that do on an AFE like OFON-1?', '["Nothing distorting, since the engine bends the plan around the rig schedule.", "It names the late lines, since SPI is formed line by line and the dashboard reports the lowest of the line indices.", "Drilling done early lifts it and completion still to come drags it, since every day of the plan costs the same.", "It counts the days of delay, since planned value converts each dollar behind the plan back into calendar days on the window."]'::jsonb, 2, 'OFON-1 carries 14200000 of drilling, usually spent early, and 5600000 of completion, usually spent late, and the plan gives each of the 302 days the same share of 27050000.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 1, 'OFON-1 reports SPI 1.141290 as of 2027-06-30 and 0.872063 as of 2027-08-15, with earned value 15231500 in both reports. What moved between them?', '["Earned value, which the engine re-weights by the days elapsed so that the same progress is worth less later in the window, leaving the planned value where it was.", "Planned value alone, from 13345861 to 17466060, because the budget is spread over more elapsed days while the progress column stood still.", "CPI, which fell as invoices arrived between the two dates and took SPI down with it through their shared earned value.", "The EAC, which absorbed the overrun of -550000 between the reports and raised the plan that SPI is divided by."]'::jsonb, 1, 'Only time progress, planned value and SPI move with the as-of date; 15231500 over 13345861 gives 1.141290 and over 17466060 gives 0.872063.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 2, 'Which set of OFON-1 numbers is identical in a report dated 2027-01-15 and one dated 2028-01-10?', '["Time progress and planned value, since both are clamped at the edges of the window and every date outside it reads the same clamp.", "SPI and CPI, since both are ratios of numbers read from the lines and a ratio of fixed numbers cannot drift with the calendar.", "Planned value and earned value, since both are the budget of 27050000 weighted by a fraction and neither fraction is dated.", "Earned value 15231500, CPI 1.009377, actuals 15090000 and the EAC of 27600000."]'::jsonb, 3, 'The lines as entered carry no date, so earned value, actuals, CPI and EAC read the same on every as-of date, while time progress runs from 0.000000 on the first date to 1.000000 on the second.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 3, 'OFON-1''s window opens on 2027-02-01. What SPI does the repaired engine report as of 2027-02-01 itself?', '["1.000000, because on the start day the job is exactly on schedule.", "Infinity, because earned value of 15231500 is divided by a planned value of 0 and the division is carried out as written.", "Null, because no whole day has elapsed on the start day, so time progress and planned value are both 0.", "0.563087, because a report on the boundary of the window falls back to percent complete divided by 100 as a report with no window does."]'::jsonb, 2, 'The start day reads exactly as the day before the start: time progress 0.000000, planned value 0, SPI null. Planned value first appears on the day after the start.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 4, 'A portfolio screen sorts AFEs by SPI and counts a null SPI as 0. What does that do to OFON-1 in a report dated 2027-01-15?', '["It ranks OFON-1 among the worst performers, inventing a reading of nothing earned against a real plan when the engine said no plan existed yet to measure against.", "Nothing that matters, because a null and a 0 both mean no schedule performance, and the sort only separates AFEs that have started.", "It ranks OFON-1 as exactly on schedule, since the sort treats the missing ratio as the neutral value of a performance index.", "It removes OFON-1 from the sort entirely, because a screen drops rows whose sort key cannot be compared with a number."]'::jsonb, 0, 'Null says the ratio does not exist yet. Counting it as 0 puts every AFE that has not started at the bottom; counting it as 1 hides them among the healthy ones.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 5, 'How does the engine arrive at OFON-1''s time progress of 0.645695 as of 2027-08-15?', '["The share of the budget already invoiced, the 15090000 of actuals over the 27050000 budget, read as the fraction of time used.", "195 whole days elapsed since 2027-02-01, over the 302 whole days from the start to the end of the window.", "The whole months elapsed at the first of August over the months in the window, since the plan steps once a month.", "The days elapsed since the first invoice on 2027-02-20 over the days to the end, since the plan starts when spending does."]'::jsonb, 1, 'Time progress is elapsed whole days over total days: 195 over 302 gives 0.645695, and 149 over 302 gives the 0.493377 of 2027-06-30.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 6, 'The budget of 27050000 multiplied by the printed time progress 0.493377 lands a few units away from the planned value of 13345861 the engine prints for 2027-06-30. Which figure should a report quote?', '["The product of the budget and the printed fraction, because the printed fraction is the one a reviewer can check by hand.", "Either one, because a difference of a few units on a budget of 27050000 is inside the rounding of whole-unit AFE money.", "The product of the EAC and the printed fraction, because planned value is recomputed against the forecast once the AFE overruns.", "13345861, because the engine multiplies the unrounded fraction."]'::jsonb, 3, 'The fraction prints to six decimals while the planned value comes from the full-precision fraction, 149 over 302, so the engine''s 13345861 is the number SPI was divided by.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 7, 'OFON-1''s SPI is above 1 at 2027-06-30 and below 1 at 2027-08-15. DRL-01''s rig time, 14200000 of the budget, is spent early and CMP-05''s 5600000 of completion late. What can the two SPIs be, before any slippage is assumed?', '["The shape of a well measured against a plan that is a straight line in calendar days and knows nothing about which work comes first.", "Proof that the job was ahead in June and fell behind in August, since both readings divide the same earned value by a correct plan for each day.", "A phasing error in the plan, since the engine front-loads DRL-01''s budget and the plan overshoots the work by August.", "The effect of CPI 1.009377, which scales planned value by cost performance and pulls SPI below 1 once spend outruns the plan."]'::jsonb, 0, 'The plan the engine divides by is one straight line for the whole AFE; with earned value fixed at 15231500 the ratio falls from 1.141290 to 0.872063 on the calendar alone.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 8, 'Between OFON-1''s reports of 2027-06-30 and 2027-08-15, SPI fell while earned value stayed at 15231500. What can the engine tell you about why?', '["That the work stopped, because a progress column that was not updated would have raised actuals without raising earned value and moved CPI.", "That progress went unrecorded, because a stoppage would also have stopped the plan and left SPI where it stood in June.", "Nothing that separates the two causes: the work may have stopped for those weeks, or nobody updated the progress column, and the lines look the same either way.", "That the rig stood idle, because SPI below 1 on the second date is the engine''s measure of lost working days against the window."]'::jsonb, 2, 'Planned value grew from 13345861 to 17466060 while earned value stood still, and CPI of 1.009377 on both dates never looks at the calendar, so neither index can choose between the explanations.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 9, 'As of 2028-01-10, after OFON-1''s window closed on 2027-11-30, SPI is 0.563087. What does that number measure?', '["Schedule pace against the window, which will keep falling on each later report as the AFE runs further past its end date and the plan keeps growing.", "Earned value over the whole budget, which is percent complete 56.3087 divided by 100, so it no longer measures pace against a plan.", "Earned value over the EAC of 27600000, since after the end the plan is replaced by the forecast of what the work will cost.", "The average of the SPIs reported across the window, which the engine carries forward once no further planned value accrues."]'::jsonb, 1, 'From the end day planned value is 27050000 on every date, so 15231500 over 27050000 reads 0.563087 until somebody changes progress on the lines.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 10, 'OFON-1''s planned value stops at 27050000 on and after its end day, though its EAC is 27600000. What does that mean for a late AFE that is also overrunning?', '["Its SPI is overstated by the overrun, because the engine switches planned value to the EAC after the end and earned value does not follow.", "Its overrun of -550000 appears as a schedule loss, because planned value absorbs the variance at completion on the end day.", "Nothing, because SPI stops being reported once the window has closed.", "It is measured against the approved budget, the smaller number, because the forecast never enters planned value."]'::jsonb, 3, 'Planned value is the budget times time progress, so the most it can be is 27050000; setting planned value against the EAC and calling the overrun a schedule problem is a documented mistake.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 11, 'The published case with no window dates returns time progress 1.000000 and SPI 0.250000. What does the engine do with an AFE saved without a window?', '["Refuses it with AfeInputError, because planned value cannot be formed without a start date and an end date.", "Reports SPI null, as it does before the start, because with no window no day has elapsed inside it.", "Reports it as though the window had already ended, dividing earned value by the whole budget, a fallback EC5-0 did not change.", "Measures it against today, treating the report date as the end of the window so that time progress is always 1 on the day it runs."]'::jsonb, 2, 'The fallback to time progress 1 remains in the engine as published, and the repaired Suite labels SPI unavailable for such an AFE; a low SPI there is not a late project.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 12, 'An as-of date of 30 February is passed to an AFE that has no window dates at all. What does the engine return?', '["A refusal, AfeInputError: \"asOf is not a valid date\", even though the AFE has no window the date could be placed in.", "Time progress 1.000000 and the no-dates SPI, because without a window the as-of date is never read and cannot be wrong.", "A report dated the first valid day after the typed one, since the date parser rolls an impossible day forward into March.", "SPI null, because an unreadable date is treated as a date before the start, where planned value is 0."]'::jsonb, 0, 'The published refusals cover a string that is not a date, a month 13 and 30 February, and they fire on an AFE with no window as well.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 13, 'Before EC5-0 the AFE wizard asked for no dates. What SPI would a report on OFON-1 have shown on its first day of drilling?', '["Null, because a report on the first day of drilling falls on the start of the window, where no whole day has elapsed.", "Infinity, because the old engine divided earned value by a planned value of 0 whenever it was run before the plan had grown.", "1.141290, because the old engine read the clock and the first day of drilling came early in the window, where the plan was small.", "0.563087, the same as on its last day."]'::jsonb, 3, 'With no window, time progress fell back to 1, so SPI equalled percent complete 56.3087 divided by 100 on whatever day the report was opened.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 14, 'A monthly pack labelled as of 2027-08-15 divides OFON-1''s earned value of 15231500 by a planned value of 13345861 and prints 1.141290. What went wrong?', '["Nothing, because earned value and CPI are the same on both dates, so SPI is too and the pack simply chose the more favourable planned value.", "The earned value is stale, because earned value as of 2027-08-15 is larger than in June and the numerator should have been updated with it.", "The planned value belongs to 2027-06-30, so the pack reports June''s SPI under August''s date; as of 2027-08-15 planned value is 17466060 and SPI 0.872063.", "The pack used planned value where it should have used actuals of 15090000, which is the August denominator the engine divides by."]'::jsonb, 2, 'Dividing an earned value from one date by a planned value from another is the second form of the undated SPI; the engine''s planned value for 2027-08-15 is 17466060.'),
  ('portfolio', 'intermediate', 'module', 'm04-the-as-of-date', 15, 'A report dated 2027-01-15, before OFON-1''s window opens, shows earned value 15231500 from DRL-01 at 72.0000 percent and CSG-02 at 100.0000 percent. What does the engine make of that?', '["It sets earned value to 0 before the start, since work cannot be earned before a window opens, and reports CPI null beside it.", "It reports it without complaint, since it never asks whether progress is plausible for the date, so the reader must suspect the window or the progress column.", "It flags the AFE invalid, since earned value above planned value of 0 is the case the EC5-0 repair was written to catch.", "It reports SPI null and zeroes the progress it cannot schedule, leaving only CSG-02''s finished line in earned value."]'::jsonb, 1, 'Before the start SPI is null, but earned value 15231500, CPI 1.009377 and the EAC of 27600000 are all still reported, because they are read from the lines and not from the calendar.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 1, 'OFON-1''s S-curve as of 2027-08-15 opens on a point labelled "Feb 27". What does that label denote?', '["The 27th of February, the monthly billing cut-off to which each point''s invoices are summed.", "The last day of February 2027, since each point closes its month and carries that month''s invoices.", "February 2027, a short month name and a two-digit year, on a point standing on the start date 2027-02-01 with every column cumulative to that day.", "Point 27 of the window, counted in days from the start, which is where the first bucket is closed."]'::jsonb, 2, 'Each point sits on the start date stepped forward by whole months, the 1st on OFON-1, so the invoice of 2027-02-20 shows an Actual of 0 at Feb 27 and first appears at Mar 27.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 2, 'A monthly report reads OFON-1''s "Jul 27" Actual of 12700000 as spend to the end of July, then flags an August spike of 2390000 at "Aug 27". What happened?', '["The invoice of 2027-07-18 is dated after the 1 July point and first counts at the 1 August point, so the spike is a reading of the labels and no August spending.", "The invoice was billed in July but paid in August, and the curve records invoices when they are paid.", "August''s point includes the commitments on the lines, which enter the Actual line once a month closes.", "The curve lags spend by one bucket by design, so the August point is July''s spend delayed to hold accruals out."]'::jsonb, 0, 'Actual at a point counts invoices dated on or before that day, so Jul 27 holds 3100000, 5200000 and 4400000, and 2390000 takes Aug 27 to 15090000.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 3, 'OFON-1''s metrics report planned value 17466060 as of 2027-08-15. Where does that number sit on the S-curve drawn at the same as-of date?', '["On the Aug 27 point, which the engine moves to the as-of date whenever the date falls inside that month, so the chart and the SPI agree.", "On the Forecast line, where planned value is redrawn from the EAC.", "On the Sep 27 point, because the curve rounds the as-of date forward to the next bucket so that the plan it shows is never understated.", "On no point: it falls between Aug 27 at 16212086 and Sep 27 at 18988742, since no bucket stands on the as-of date."]'::jsonb, 3, 'The buckets are a fixed monthly grid with no point on the as-of date, so the planned value SPI 0.872063 was divided by is not plotted, and earned value 15231500 is not plotted at all.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 4, 'OFON-1''s Planned line adds 2687086 into the May 27 point but 2776656 into the Aug 27 point. Why do the steps differ?', '["The plan is phased by cost line, and DRL-01''s rig time weights the drilling months more heavily than later ones.", "The plan is straight in calendar days, so a month with more days adds more plan.", "Each step is the budget less the invoices so far spread over the months left, so it changes as invoices arrive.", "The engine rounds each point to whole units separately, and the rounding error accumulates into alternating steps."]'::jsonb, 1, 'Planned is the budget of 27050000 times elapsed days over the days in the window; the month into May 27 is shorter than the month into Aug 27, so it adds 2687086 against 2776656.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 5, 'A planner wants OFON-1''s Planned line to front-load DRL-01''s 14200000 of rig time and hold CMP-05''s 5600000 of completion to the end. What does the engine offer?', '["A phasing field on each line, which reshapes the Planned line once every line carries a start and end month of its own.", "Nothing: it draws one straight line for the whole AFE, with no plan per line and no phasing to enter, charging every calendar day an equal slice of the budget.", "An S-shaped plan by default, since the curve''s name promises one and the straight line appears only for an AFE with a single line, which the engine bends to the invoices.", "A plan per line summed across the window, which the engine builds from each line''s progress so that finished work is planned early."]'::jsonb, 1, 'The plan has no shape the user can give it, so an Actual above Planned at Mar 27 and below it at Apr 27 is an invoice date meeting a straight line and not news about the well.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 6, 'At OFON-1''s Aug 27 point the Actual is 15090000 and the Planned is 16212086. A reader calls the gap "behind schedule". What is the gap?', '["Earned value below planned value on the day of the point, which is the curve''s plot of SPI in money rather than as a ratio at each of the monthly buckets it draws.", "Commitments not yet invoiced, which the Actual line holds back until billing and which the Planned line already includes.", "Spend below a straight budget line, a cost comparison with no progress in it; the schedule measure is SPI 0.872063, earned value over planned value.", "Schedule slippage in money, since planned value and actual cost measured on the same day together form the schedule variance that the curve plots at every point."]'::jsonb, 2, 'SPI divides earned value, 15231500 from the progress column, by planned value; the curve never plots earned value, so no gap on it is a schedule reading.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 7, 'On a live AFE the cost lines'' actuals total more than the S-curve''s last Actual at or before the as-of date. What is each describing?', '["Percent spent and CPI describe the actuals typed on the lines, the Actual line describes the dated invoices, and nothing on the screen says which is which, so the difference is a question about accruals, billing or a missing date.", "The same money on two schedules, since the curve converts line actuals into invoices by date and the gap is spend not yet reached by a bucket.", "An error in the engine, since it forces the invoices to match the lines and a gap can only mean the curve was drawn before a repair.", "Commitments, since the lines carry actual plus commitment and the curve carries the actual alone, and the gap is what is on order."]'::jsonb, 0, 'The metrics sum the actual column and the S-curve sums invoices; on OFON-1 both read 15090000 because the teaching field was written to match, which teaches the wrong habit.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 8, 'A published case bills two invoices over a past window: 100 with no date field and 200 whose date is null. The first and last points both read an Actual of 200. What happened to each invoice?', '["Both are held back to the as-of date, since an undated invoice cannot be placed in a bucket, and 200 is the larger of the two carried as a floor.", "The engine refuses the missing field and drops that invoice with a warning, while it books the null date at the start of the window as an opening balance.", "Both count on the as-of date, the only day an undated invoice can take.", "The null date is read as a day in 1970 and counts in every bucket; the missing date never counts. Neither is refused or flagged."]'::jsonb, 3, 'A curve that starts above zero is the tell; the engine as published refuses neither invoice, so check every invoice has a date before trusting the first point.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 9, 'OFON-1''s Forecast reads 15090000 at Aug 27 and 19374834 at Sep 27, the first point after the as-of date of 2027-08-15. What is the step?', '["The spend expected in September, the EAC less the actuals to date spread over the months left in the window.", "A change of formula: past the as-of date the Forecast is the EAC spread from the start of the window, ignoring the actuals it follows.", "The commitments of 5000000 falling due in the first month after the report, added onto the last Actual as they are billed by the contractors.", "A burn rate taken from the last invoices and carried forward from 15090000, which is why the step repeats at each projected point until the end."]'::jsonb, 1, 'The projection never starts from 15090000 and adds spend still to come; the step''s size depends on how far the actuals sit from a straight line, which says nothing about September.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 10, 'Why does OFON-1''s Forecast sit above Planned at every projected point, 19374834 against 18988742 at Sep 27 and 24949669 against 24452483 at Nov 27?', '["It scales the plan by CPI 1.009377, so every projected point is lifted by the cost performance of the work done so far.", "It adds the commitments of 5000000 to the plan from the as-of date, since committed money is certain to be spent.", "It is the Planned line redrawn with the EAC of 27600000 in place of the budget of 27050000.", "It carries forward the gap between Actual and Planned at the last actual point, holding that gap constant to the end."]'::jsonb, 2, 'The EAC exceeds the budget by a variance at completion of -550000 and the whole projected line carries that ratio; earned value and CPI play no part in the projection.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 11, 'Before EC5-0, editing a line in the Suite copied its budget into its forecast. What would that have done to CSG-02 and to OFON-1''s Forecast line?', '["The copy is a positive entered forecast, so the rule takes 3900000 whatever CSG-02 has spent, hiding its line variance of -400000 and settling the Forecast line toward the Planned line.", "Nothing to CSG-02, because the rule compares an entered forecast with actual plus commitment and keeps the larger 4300000.", "It would have raised CSG-02''s forecast to its actual, since a copied budget is recognised as a default and ignored by the rule.", "It would have removed CSG-02 from the EAC, since a forecast equal to the budget carries no variance and the line drops out."]'::jsonb, 0, 'An entered forecast that is positive wins under the one rule, so a copied 3900000 replaces the 4300000 already spent; the repaired app no longer copies.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 12, 'OFON-1''s last Planned point, Nov 27, is 24452483 against a budget of 27050000. Does the engine''s planned value itself stop short of the budget?', '["Yes, because the curve spreads the budget over the months before the end month and leaves the final month for contingency that is never planned.", "Yes, because the engine deducts the 2597517 held for the month the as-of date falls in, and releases it once a later report is run.", "No, because the curve rescales its last point to the budget when the chart is drawn, and 24452483 is only the value in the underlying table.", "No. The curve has no point on the end day; the metrics show 27050000 there."]'::jsonb, 3, 'The walk steps from 2027-02-01 by whole months; the next step, the first of December, falls after 2027-11-30, so the chart stops 2597517 short, a property the EC5-0 repair left in place.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 13, 'A published window from 2090-01-01 to 2091-01-01 returns 13 points with a last Forecast of 2450, the whole EAC. Why does that curve reach its EAC when OFON-1''s last Forecast of 24949669 falls short of 27600000?', '["Its window lies in the future, so the whole curve is projection and a projected line always runs to the EAC, while OFON-1''s mixes actuals in.", "Its end date falls exactly on a monthly step, so a point stands on the end day; OFON-1''s end, 2027-11-30, is not on a step from 2027-02-01.", "It has no invoices, so no actuals hold the forecast back, while OFON-1''s four invoices pull its projected points below the EAC.", "It is thirteen months long, and the engine closes any window of more than a year on its end date, while OFON-1''s is shorter."]'::jsonb, 1, 'The published one-year window 2020-01-01 to 2020-12-31 stops short the same way as OFON-1, with 12 points and a last Planned of 1101, because its last step lands on the first of December.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 14, 'The digest draws OFON-1''s first point as "Feb 27" with the timezone pinned to UTC. Drawn in America/Los_Angeles, the same AFE labels its first point "Jan 27" and every Planned value shifts. Why (finding EC5-5)?', '["The Suite converts AFE money into the viewer''s local currency, which rescales the Planned line and relabels the buckets.", "The Planned line is recomputed from today''s date in the viewer''s timezone, so a Pacific viewer sees a later as-of date.", "The engine parses the window as UTC midnight but steps months and prints labels in local time, so west of UTC the start lands on the previous evening.", "Invoices are stored in local time, and in Los Angeles the first invoice moves into January and carries the label with it, along with every Planned value that follows."]'::jsonb, 2, 'The metrics are unaffected, and Lagos, Tokyo and UTC agree with the digest''s table; a curve compared across offices can disagree on every Planned point.'),
  ('portfolio', 'intermediate', 'module', 'm05-the-s-curve', 15, 'Before EC5-0 a 2020 AFE drew 81 points on 2026-09-14 and gained one a month. What did the repair change, and what did it leave?', '["It now closes the curve on the as-of date, so an AFE read after its end draws no points beyond the day of the report.", "It now adds a final point on the end day, so the last Planned value of every curve equals the budget of the AFE.", "It now limits the curve to twelve points, the length of the longest window the Suite''s wizard accepts for an AFE.", "The walk now stops at the end date; the plan stopping short of the budget was not repaired."]'::jsonb, 3, 'The repaired curve for the published window 2020-01-01 to 2020-12-31 has 12 points ending at Dec 20 with a last Planned of 1101, still short of its budget of 1200.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 1, 'A graded reading of OFON-1 is worked with every calculation right, but the explorer was left on its default as-of date of today instead of 2027-08-15. Which of its metric readings are wrong?', '["Every number that depends on the lines, since the explorer recomputes earned value and the EAC for the date it is set to.", "Earned value, CPI and SPI, since all three divide by a figure the engine reads on the day the report is run.", "None, since the dashboard passes today as the as-of date and a report run today is the current reading of the AFE.", "Only time progress, planned value and SPI."]'::jsonb, 3, 'EAC 27600000, variance -550000, earned value 15231500 and CPI 1.009377 are identical at every date, so the answer looks complete while its SPI answers a different question from 0.872063.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 2, 'Working OFON-1 in the order lines, forecast, earned value, date, curve, at which step does an entered forecast that is not positive first become visible?', '["The curve step, where the Forecast line jumps at the as-of date on any line whose entered forecast was ignored by the rule, lifting that line above the Planned line.", "The forecast step, where the branch each line took is written, because the rule ignores that figure and the line''s fallback looks ordinary in the EAC.", "The earned value step, where a line with no usable forecast earns nothing on its progress and pulls CPI down.", "The date step, since an entered forecast of 0 or less is treated as unplanned work and zeroes that line''s planned value."]'::jsonb, 1, 'The published negative forecast case returns EAC 100.0000 and variance 0.0000 with an entered -50, a total that shows nothing, so only the named branch on the line reveals it.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 3, 'OFON-1''s variance at completion is -550000. DRL-01, LOG-04 and CMP-05 each show a line variance of 0. What do those three zeros say?', '["Only that spend and commitment have not yet passed the budget on those lines; with no entered forecast a line can never show a saving, so 0 is the rule''s floor, and the whole -550000 is CSG-02''s -400000 plus CMT-03''s -150000.", "That the three lines are on budget, since the rule forecasts each at the larger of budget and spend and none has gone over.", "That the three lines are under budget by their unspent balances, which the rule nets against the overruns on the other two.", "That the three lines are complete, since the forecast rule reports a zero variance once a line''s progress reaches its budget."]'::jsonb, 0, 'DRL-01 has 12400000 spent and committed against 14200000; its forecast is still 14200000, and any overrun still to come on drilling, logging or completion is not in the -550000.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 4, 'With CMT-03''s budget of 1250000 and the 940000 already spent and committed, an entered forecast of 900000 gives an item forecast of 900000, and an entered forecast of 0 gives 1250000. What does the pair show?', '["The rule floors an entered forecast at the spend plus commitment, and 900000 passed only because it is within tolerance of 940000.", "The rule treats 0 as a request to close the line at budget and 900000 as a request to cut scope, so both are honoured.", "Any positive entered forecast is taken as typed, even one below the money already spent and committed (finding EC5-1), while 0 is not positive and falls back to the larger of budget and spend plus commitment.", "The rule reads 900000 as a saving to be booked against the budget, which is why the variance on that line becomes positive at once."]'::jsonb, 2, 'The same line with an entered forecast of 1 forecasts 1, so a typing slip passes straight into the EAC, and a forecast of 0 meant as a descope saves nothing on the report.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 5, 'A partner sees OFON-1''s cost performance index above 1 on one tile and an overrun of 550000 on another, and suspects one tile is wrong. What should the partner be told?', '["CPI compares earned value from typed progress with actuals to date, while the EAC applies the forecast rule line by line, so CSG-02''s spend and CMT-03''s entered 1400000 overrun the budget whatever the index says.", "They cannot both be right, since CPI above 1 means spend is below earned value and the forecast must then finish under the budget.", "CPI includes the commitments of 5000000 and the EAC does not, so the index is flattered by money that has not been spent yet.", "The EAC is dated at the end of the window and CPI at the as-of date, so the overrun is expected after 2027-08-15 and not before it."]'::jsonb, 0, 'DRL-01, CMT-03 and LOG-04 earn more than they spent and carry CPI over 1, while the EAC of 27600000 comes from each line''s branch of the one rule.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 6, 'CSG-02 is 100.0000 percent complete, with a budget of 3900000 and an actual of 4300000. What does it contribute to OFON-1''s earned value?', '["Its actual of 4300000, since a finished line has earned whatever it cost to finish, and its CPI on the line is then exactly 1.", "Its forecast of 4300000, since earned value weights progress by the item forecast once the rule''s actual plus commitment branch is taken.", "Nothing yet, since earned value counts a line only when its invoices match its actuals, and CSG-02 has spent past the authorised sum.", "Its budget, 3900000."]'::jsonb, 3, 'Earned value pays each line what the work was authorised to cost, so CSG-02 is the one line earning less than it spent, 3900000 against 4300000.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 7, 'Write OFON-1''s SPI as of 2027-01-15, 2027-08-15 and 2028-01-10. Which triple, with its reasons, is right?', '["0 before the window opens, since nothing was planned; 0.872063 inside it; and 1.000000 after the end, where the whole plan has been reached.", "Null before the window opens, where planned value is 0; 0.872063 inside it, earned value 15231500 over planned value 17466060; and 0.563087 after the end, which equals percent complete divided by 100.", "Null before the window opens; 1.141290 inside it, since the dashboard reads the planned value of the month the date falls in; and null after the end, when the plan is spent.", "0.563087 before the window opens, where the engine falls back to percent complete; 0.872063 inside it; and 0.563087 after the end."]'::jsonb, 1, 'Only time progress, planned value and SPI move with the as-of date, so the three SPIs are three readings of the same lines on three days.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 8, 'The published weighted earned value case reports earned value 110.0000, actuals 0.0000 and CPI 1.000000. How should a reader take that CPI?', '["As on budget, since the work earned was delivered for nothing and an index of 1 is the cost neutral reading that the engine reports.", "As a refusal marker standing in for null.", "As the ratio of earned value to planned value, since with no spend the engine substitutes the schedule index for the cost index on that AFE.", "As undefined: the engine returns CPI 1 whenever actuals are 0."]'::jsonb, 3, 'The finding is recorded and not repaired, so CPI 1.000000 beside any earned value with no spend, 110.0000 here, is a division the engine declined to do and printed as a neutral number.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 9, 'Why does a graded AFE reading compare the cost lines'' actuals with the invoice total before any metric is quoted?', '["Because the engine refuses to compute CPI until the two totals agree, so a mismatch has to be cleared before the dashboard will load its tiles or export a report.", "Because the forecast rule reads actual plus commitment from the invoices, so a mismatch changes the EAC and has to be settled before the forecast branches are named.", "Because the metrics read the lines and the S-curve reads the invoices, so if the totals differ the two describe different money, and that belongs at the top.", "Because the invoice total is the audited figure, and the engine replaces line actuals with it on the as-of date whenever they differ."]'::jsonb, 2, 'On OFON-1 both read 15090000 because the field was built that way; on a live AFE an accrual on a line or an invoice booked before the line is updated separates them, and an invoice with a null date counts from 1970.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 10, 'A reader takes OFON-1''s last Forecast point, 24949669, as the money the job will spend, and calls the rest of the EAC of 27600000 a saving. What went wrong?', '["The curve stops at its Nov 27 point, standing on the first of November, before the end of the window, so the EAC is read from the metrics and only the shape from the curve.", "The reader used the Forecast line where the Actual line applies, since past the as-of date the Actual line carries the committed spend to the end.", "The reader ignored the as-of date, since the last Forecast point moves up to the EAC once a report is run after the window''s end, when every projected point has become an actual.", "Nothing, since the projected line nets the entered forecasts against their budgets and the gap is the saving it has identified."]'::jsonb, 0, 'The last Planned point, 24452483, is short of the budget of 27050000 in the same way, a property of the engine as published; neither gap is money the job will not spend.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 11, 'As of 2027-08-15, which of OFON-1''s earned value, CPI and SPI can be rebuilt from the S-curve alone?', '["SPI, as the Actual at the Aug 27 point over the Planned at the same point, since both are cumulative to that day.", "Earned value, as the Forecast at the as-of date, since the curve projects the work done onto the window from the start.", "CPI, as the last Actual over the last Planned point, since both lines are drawn on one budget and share its denominator.", "None of them."]'::jsonb, 3, 'The curve plots no earned value, no point stands on the as-of date, and planned value 17466060 falls between Aug 27 and Sep 27, so SPI 0.872063 and CPI 1.009377 come only from the metrics.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 12, 'Two exports of OFON-1 from the repaired Suite agree on an EAC of 27600000 but show different SPIs. Where should the check start?', '["At each line''s forecast field, since after EC5-0 the exports still apply different forecast rules and a copied budget changes SPI.", "At the invoices, since the S-curve feeds SPI and a late invoice moves the ratio in one export and not in the other.", "At the as-of date each export was run for.", "At the progress column, since progress is the only input SPI reads and the EAC agreeing proves the dates were the same."]'::jsonb, 2, 'After EC5-0 every screen shares one forecast rule, so the EAC agrees; SPI moves with the date, 1.141290 on 2027-06-30 and 0.872063 on 2027-08-15 on identical lines.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 13, 'A manager says OFON-1 is "55.7856 percent done" and cites its SPI of 0.563087 after the end as agreement. What has been mixed up?', '["Nothing, since SPI after the end is actuals over the budget and both numbers describe spend against the approved figure, read on the same basis at the same date.", "55.7856 is percent spent, actuals over budget, while 0.563087 after the end is percent complete 56.3087 divided by 100, work recorded as done.", "The manager has quoted CPI as a percentage, since 55.7856 is the cost index scaled by 100 and SPI after the end rounds to it.", "The SPI belongs to a report without dates, since an AFE with a window never reports SPI after its end day."]'::jsonb, 1, 'Percent spent and percent complete share the budget as denominator, and dividing one into the other gives CPI 1.009377; spend is not work.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 14, 'The tier ends on the sentence that an AFE report is a forecast rule, a date and the progress typed on the lines. Which pairing of number to input is right?', '["The EAC rests on the forecast rule, earned value on the typed progress, and SPI on both the typed progress and the as-of date.", "The EAC rests on the as-of date, earned value on the forecast rule, and SPI on the typed progress alone, since the forecast is dated by the report.", "The EAC rests on the typed progress, earned value on the as-of date, and SPI on the forecast rule.", "The EAC and earned value rest on the forecast rule, and SPI on the as-of date alone, since progress enters neither the EAC nor the schedule index."]'::jsonb, 0, 'EAC 27600000 is the rule''s branches summed, earned value 15231500 is progress weighted by budget, and SPI 0.872063 divides that earned value by the planned value of 2027-08-15.'),
  ('portfolio', 'intermediate', 'module', 'm06-the-professional-reading', 15, 'A capstone answer gives OFON-1''s planned value at the end of its window as 24452483, read off the last Planned point of the S-curve. Where should it have been read?', '["From the Forecast line''s last point, 24949669, since the plan at completion is the EAC once the AFE has overrun its budget.", "From the S-curve, which is the plan of record.", "From the metrics as of 2027-11-30, which give 27050000.", "From the metrics as of 2027-08-15, since planned value is fixed on the as-of date and is not carried to the end of the window."]'::jsonb, 2, 'The walk stops at the first of November because the next step falls after 2027-11-30, so the chart ends 2597517 short; on the end day time progress is 1 and planned value the whole budget.'),
  ('portfolio', 'intermediate', 'final', null, 1, 'LOG-04 on OFON-1 carries an actual of 350000 and a commitment of 900000 against a budget of 2100000. Which of the AFE''s readings does that 900000 enter?', '["Percent spent, which counts money paid and money contracted together, so the 55.7856 on OFON-1 already carries the whole 5000000 committed across the lines.", "Earned value, because a contracted order is work the line has secured, and the engine credits committed money at the line''s progress percent.", "Only the forecast rule''s comparison of the budget with actual + commitment, where 1250000 still falls short of 2100000, so the line forecasts its budget.", "The S-curve''s Actual line, which adds each line''s commitment on the as-of date so that the curve and the forecast read the same money."]'::jsonb, 2, 'Percent spent is the 15090000 of actuals over 27050000 and earned value is budget times progress, so the 5000000 committed on OFON-1 sits outside both and can only lift an EAC.'),
  ('portfolio', 'intermediate', 'final', null, 2, 'For the report dated 2027-06-30, OFON-1 prints percent complete 56.3087 and time progress 0.493377. How do those two figures combine into the SPI of 1.141290?', '["SPI is percent complete over 100 divided by time progress, because earned value and planned value are both fractions of the same 27050000 budget.", "SPI is percent complete over 100 multiplied by CPI, because the schedule index corrects the recorded progress for what the work actually cost to buy.", "SPI is time progress divided by percent complete over 100, the calendar''s share of the window set over the work''s share of the whole authorised budget.", "They do not combine: SPI divides earned value by actuals to date, and time progress decides only whether the SPI is shown on the report or printed as null."]'::jsonb, 0, '0.563087 over 0.493377 gives 1.141290 up to the rounding of the printed figures, and from the end day, where time progress is 1.000000, the same division leaves 0.563087.'),
  ('portfolio', 'intermediate', 'final', null, 3, 'The dashboard shows OFON-1''s EAC as 27600000, while the last point of the S-curve''s Forecast series, Nov 27, reads 24949669. A partner concludes the chart runs on a different forecast rule. What is the better reading?', '["The curve forecasts each line at its budget less its actual, the export rule from before the repair, so the projection carries none of the overrun on CSG-02 or CMT-03 and ends lower.", "The curve projects spend from the invoices at the pace of the last four, so its Forecast is a burn-rate estimate that happens to land short of the rule''s EAC.", "The curve''s Forecast is the budget redrawn, and the distance between the two figures is the variance at completion of -550000 that the tiles report.", "Both carry the same EAC from the one itemForecast rule; the curve spreads it evenly from the start and its last monthly point stands on the first of November, before the end date."]'::jsonb, 3, 'Past the as-of date the Forecast is the EAC of 27600000 spread from 2027-02-01, and the walk stops at Nov 27, so the chart ends at 24949669 while the rule behind both figures is the same.'),
  ('portfolio', 'intermediate', 'final', null, 4, 'In the published case "past window, all invoices unpaid: none dated", the single line has a budget of 1200 and no actual typed on it, while the S-curve reads an Actual of 200 from its first point to its last. What does each record say was spent?', '["Both say 200, because the engine copies the invoice total into a line''s actual whenever the line has none typed, so the two records agree on every screen.", "The line says nothing has been spent; the curve shows the 200 whose null date was read as 1970 and omits the 100 that had no date field at all.", "Both say 300, because the curve places every undated invoice on the window''s start date and the metrics sum the same undated invoices from the list.", "The line says 200 and the curve 300, because the line column counts only money with a date while the curve counts every invoice entered against the AFE."]'::jsonb, 1, 'The metrics read the line column and the curve reads the invoices, and nothing reconciles them: one null date counts at every point from the first, and one missing date never counts.'),
  ('portfolio', 'intermediate', 'final', null, 5, 'Between OFON-1''s reports dated 2027-06-30 and 2027-08-15 the lines were not touched. SPI falls from 1.141290 to 0.872063 and CPI holds at 1.009377. A manager takes the steady CPI as proof the crew kept working at budgeted efficiency through those weeks. What is wrong with that?', '["Nothing, since CPI and SPI share earned value as their numerator, and a CPI that holds while spend rises pins the growth in earned value to the growth in spend over the period.", "CPI is earned value over actuals read from the lines as entered, so it prints 1.009377 on both dates whether the rig worked or nobody updated the progress column.", "CPI is taken against planned value on the report date, so it should have fallen with SPI, and its steadiness shows that one report was exported before the repair.", "A steady CPI beside a falling SPI means spend fell in step with progress, which is the signature of a rig held on standby at a reduced day rate."]'::jsonb, 1, 'Earned value stood at 15231500 while planned value grew from 13345861 to 17466060; neither CPI nor SPI can say whether the work stopped or the progress was simply never updated.'),
  ('portfolio', 'intermediate', 'final', null, 6, 'To descope OFON-1''s completion work, one engineer proposes typing 0 into CMP-05''s forecast field and another proposes setting CMP-05''s budget to 0. What does each do to the report?', '["Both cut the EAC by the line''s whole budget, because the rule reads a zero in either field as the line''s removal from the AFE.", "The forecast of 0 cuts the EAC by the line''s budget, while the budget of 0 is refused because a line cannot be forecast without an authorisation behind it.", "Both leave the EAC at 27600000, because the fallback keeps a line''s original budget once any money has been committed against it.", "The forecast of 0 changes nothing; the budget of 0 leaves CMP-05 forecasting its 1200000 still committed and shrinks the AFE budget, which also moves planned value, percent spent, percent complete and SPI."]'::jsonb, 3, 'A forecast of 0 is not positive, so the line keeps forecasting the larger of 5600000 and 1200000; with a budget of 0 the larger is the 1200000 of orders placed, and every reading divided by the budget moves with it.'),
  ('portfolio', 'intermediate', 'final', null, 7, 'A reviewer checks OFON-1''s SPI of 0.872063 as of 2027-08-15 by dividing earned value by the Planned value printed at the Aug 27 point of the S-curve drawn at the same date. What happens?', '["The check divides by 16212086, the plan on the first of August, and cannot reproduce the engine, whose 17466060 stands on the as-of date and sits on no point of the curve.", "The check reproduces the engine, because the curve''s point for the month holding the as-of date is by construction the same planned value that the SPI of 0.872063 is divided by.", "The check fails because the curve''s Planned line is built from the dated invoices while the SPI''s planned value is built from the line budgets.", "The check fails because the Aug 27 point stands on the last day of August, after the as-of date, and so overstates the plan the SPI was measured against."]'::jsonb, 0, 'Points stand on the start date stepped by whole months, so 17466060 falls between Aug 27 at 16212086 and Sep 27 at 18988742, and earned value is not plotted at all.'),
  ('portfolio', 'intermediate', 'final', null, 8, 'DRL-01''s progress is retyped from 72.0000 to a figure past 100 percent, and nothing else on OFON-1 changes. What does the repaired engine do?', '["It refuses the figure with a message naming the cost item, because its own message says progress runs from 0 to 100 percent.", "It silently clamps the figure to 100 percent on the way in, so DRL-01 earns exactly its 14200000 budget and no reading can pass what the line was authorised to cost.", "It accepts the figure: DRL-01 earns more than its 14200000 budget, so earned value, CPI, percent complete and every non-null SPI rise, while the EAC stays at 27600000.", "It accepts the figure and lowers the EAC, because the forecast rule reads progress past 100 percent as work bought for less than its budget."]'::jsonb, 2, 'The published case "progress beyond 100 percent earns beyond the budget" returns EV 150.0000 and CPI 1.666667; only negative progress is refused, and the forecast rule never reads progress.'),
  ('portfolio', 'intermediate', 'final', null, 9, 'OFON-1''s invoice of 2390000, dated 2027-07-18, is found to have been billed in June and is redated to a June day. As of 2027-08-15, what changes?', '["The Aug 27 point falls by 2390000, because each point now carries only the invoices dated in its own month and none from earlier.", "Percent spent and CPI rise for the June report, because the metrics read every invoice dated on or before the as-of date.", "Nothing on the curve, because an invoice is placed by the month in which it was recorded, and the redate changes only the invoice list.", "The Jul 27 point''s Actual rises to 15090000 while the Aug 27 point is unchanged, and CPI, percent spent and the EAC do not move."]'::jsonb, 3, 'Each point is cumulative to the first of its month, so Jul 27 moves from 12700000 to the full 15090000; the metrics read the line actuals, which were never touched.'),
  ('portfolio', 'intermediate', 'final', null, 10, 'One line carries an entered forecast of -50; another, Completion, carries progress of -0.5 percent. How does the repaired AFE engine treat the two entries?', '["Both are refused with an AfeInputError naming the cost item, because the repair added one guard against negative entries across every column of a line.", "Both are clamped to zero without a message, so the forecast becomes 0 and falls back to the rule, while the progress earns nothing on the line.", "The forecast is dropped without a word and the line falls back to the larger of its budget and actual + commitment; the progress stops the calculation with a message naming the cost item.", "The forecast is refused with a message, since a negative cost cannot be forecast, while the progress is clamped to zero so earned value can still be summed."]'::jsonb, 2, 'The published line with a forecast of -50 returns EAC 100.0000 and variance 0.0000 silently, while negative progress fails with "Progress runs from 0 to 100 percent."'),
  ('portfolio', 'intermediate', 'final', null, 11, 'CPI, SPI and percent complete each put OFON-1''s earned value of 15231500 over something. Which of the three denominators moves with the as-of date?', '["Only SPI''s planned value; CPI divides by the 15090000 of actuals and percent complete by the 27050000 budget, both read from the lines.", "All three, since the actuals, the planned value and the budget are each taken as they stood on the date that the report is run for.", "CPI''s and SPI''s, since the actuals to date are read as of the report and grow with the calendar in just the same way that the planned value does.", "None of them, since the as-of date moves only the earned value in the numerator and leaves every one of the denominators where the lines put it."]'::jsonb, 0, 'SPI reads 1.141290 at 2027-06-30 and 0.872063 at 2027-08-15 on the same lines, while CPI stays at 1.009377 and percent complete at 56.3087.'),
  ('portfolio', 'intermediate', 'final', null, 12, 'CMT-03''s actual is raised by an accrual until its actual + commitment passes its entered forecast of 1400000, and no invoice is entered. What does the AFE report?', '["CMT-03 forecasts its new actual + commitment, since the rule takes the larger of the entered figure and the money already spent and committed.", "CMT-03 still forecasts 1400000, so the EAC stays at 27600000, while CPI falls and percent spent rises; the S-curve does not move.", "The EAC and the curve''s Actual both rise, since an accrual is posted to the invoices so that the two records of spend stay in step.", "CMT-03 forecasts its budget of 1250000 again, because an entered forecast below the money already spent is read as not positive."]'::jsonb, 1, 'A positive entered forecast wins unconditionally and is never compared with actual + commitment, so the line can report 1400000 on money already past it; the curve reads only the invoices.'),
  ('portfolio', 'intermediate', 'final', null, 13, 'What is the earliest as-of date on which OFON-1 reports an SPI that is not null?', '["The day after 2027-02-01, the first date on which a whole day of the window has elapsed.", "The first of March, the day the Mar 27 point stands on, where the S-curve''s Planned line first rises above 0.", "2027-02-01 itself, since the window is open on its start day and the plan begins to accrue from that morning.", "2027-02-20, the date of the first invoice, since planned value waits for spend to begin before it accrues."]'::jsonb, 0, 'On the start day time progress is 0.000000 and planned value 0, so SPI is null exactly as on 2027-01-15; the curve''s first rise, 2507947 at Mar 27, only samples a plan that began a month earlier.'),
  ('portfolio', 'intermediate', 'final', null, 14, 'DRL-01 has earned 10224000 for 9800000 spent, yet its line variance reads 0. Why can its cost performance never show as a positive line variance under the forecast rule?', '["Its 2600000 commitment is added to its earned value in the variance, and that addition cancels the gain the line made on cost.", "Line variance is taken against earned value, and 10224000 is still inside the 14200000 budget, so the rule reports 0 until the line is complete at 100.0000 percent.", "The saving is held back until the as-of date passes the window''s end, when the engine replaces each budget with a cost projected from the AFE''s CPI.", "With no entered forecast the rule takes the larger of the budget and actual + commitment, so it never forecasts under 14200000, and it never reads progress."]'::jsonb, 3, 'A zero variance is the rule''s floor: 12400000 of actual + commitment has not passed 14200000, and only an entered forecast could report DRL-01 finishing under.'),
  ('portfolio', 'intermediate', 'final', null, 15, 'Suppose editing had copied every OFON-1 line''s budget into its forecast field. What would the AFE report?', '["An EAC of 27600000 still, since three lines already forecast their budgets and the rule keeps the larger figure on the other two lines.", "An EAC equal to the budget on the dashboard, while the S-curve keeps projecting 27600000 because the curve never reads the forecast field.", "An EAC equal to the budget of 27050000 and a variance of 0: CSG-02''s spent overrun and CMT-03''s entered 1400000 are both overwritten, and the projected Forecast lies on the Planned line.", "A variance of -150000, because CMT-03''s entered forecast is protected from the copy and only CSG-02''s forecast field is overwritten."]'::jsonb, 2, 'A copied budget is a positive entered forecast and wins on every line, so the -400000 and the -150000 both vanish and the Forecast becomes the plan redrawn.'),
  ('portfolio', 'intermediate', 'final', null, 16, 'A partner''s summary shows OFON-1''s variance at completion as a positive 550000 and calls the AFE under budget. What should a reader check first?', '["Whether commitments were netted out, since the engine''s -550000 counts the 5000000 committed, and removing them turns the variance positive.", "Which way round it was taken: the engine prints budget minus forecast, so -550000 is an overrun, and a report taking forecast minus budget shows the same overrun as positive.", "Whether the summary used the as-of date, since the variance at completion moves with the report date, reads positive early in the window and turns negative only once the plan passes the spend.", "Whether CPI was applied, since a CPI of 1.009377 above 1 converts the rule''s forecast into a saving at completion of about the same size."]'::jsonb, 1, '27050000 less 27600000 is -550000: the AFE expects to spend more than it was authorised, whatever sign a flipped report prints.'),
  ('portfolio', 'intermediate', 'final', null, 17, 'Two reports both print time progress 1.000000: one on an AFE run after its end date, one on an AFE saved with no window. What in the engine''s metrics tells them apart?', '["The SPI, which is null on an AFE with no window because the engine cannot build a plan without dates to spread it over.", "The planned value, which is 0 on an AFE with no window and the whole budget on one whose end date has passed.", "Nothing: both divide earned value by the whole budget, so each SPI is percent complete over 100, and only the window fields show which AFE never had dates.", "A refusal, since the engine rejects any as-of date on an AFE with no window, printing \"asOf is not a valid date\"."]'::jsonb, 2, 'The published no-dates case returns time progress 1.000000 and SPI 0.250000, the published window read after its end returns 1.000000 and 0.940000; the repaired Suite labels SPI unavailable when there are no dates.'),
  ('portfolio', 'intermediate', 'final', null, 18, 'The published "suite test: empty AFE" returns SPI 1.000000, while OFON-1 as of 2027-01-15 returns SPI null. What separates the two?', '["The empty AFE has a budget of 0, and a guard returns SPI 1 before planned value is considered; OFON-1 has a budget and a planned value of 0, which gives null.", "The empty AFE has no window, so time progress falls back to 1 and planned value equals earned value, which makes the ratio exactly 1, the same fallback the no-dates case uses.", "OFON-1 is dated before its start and the empty AFE after its end, and the engine prints null before a window and 1 after one.", "Both are the same reading printed two ways: the empty AFE''s report came from the Suite and OFON-1''s came from the engine, which prints null for 1."]'::jsonb, 0, 'The zero-budget guard fires first, so an AFE with nothing in it reports SPI 1.000000 while one with 27050000 of budget and no planned value reports null.'),
  ('portfolio', 'intermediate', 'final', null, 19, 'OFON-1''s S-curve is redrawn as of 2027-06-30 in place of 2027-08-15. Which series is identical point for point in the two drawings?', '["Actual, since the invoices are unchanged and the curve plots every invoice dated inside the window whatever the report''s date.", "Planned, which depends only on the budget and each point''s day; Actual stops earlier and Forecast begins projecting earlier.", "Forecast, since it is the EAC spread from the start and the EAC does not move with the as-of date at any point of the window.", "None of them, since planned value scales with time progress at the as-of date and so every Planned point is redrawn with it."]'::jsonb, 1, 'Jul 27 reads Planned 13435430 in both; as of 2027-06-30 the Actual stops at Jun 27 on 8300000, and Jul 27 and Aug 27 become projected Forecast points in place of actuals.'),
  ('portfolio', 'intermediate', 'final', null, 20, 'As of 2028-01-10 OFON-1''s planned value is 27050000 and its SPI 0.563087, though its EAC is 27600000. What can still change that SPI?', '["A later as-of date, since planned value keeps climbing past the end date toward the EAC, so the SPI falls further every month the AFE runs late.", "A revised EAC, because after the end the engine divides earned value by the forecast at completion rather than by the approved budget.", "A new invoice, because after the end of the window SPI is computed from the S-curve''s Actual line in place of the typed progress.", "Only progress entered on the lines, because planned value has stopped at the approved budget and a later date or a revised EAC cannot move it."]'::jsonb, 3, 'After the end SPI is 15231500 over 27050000, percent complete over 100; the -550000 overrun never enters the schedule measure.'),
  ('portfolio', 'intermediate', 'final', null, 21, 'LOG-04 places a further order large enough that its actual + commitment passes its 2100000 budget, and nothing is invoiced or paid. Which readings move?', '["Percent spent and CPI as well as the EAC, because a placed order is counted as spend once it takes the line past its budget.", "Nothing until the order is invoiced, since commitments enter the forecast only when an invoice ties them to a line.", "The EAC only, while the curve''s Forecast stays put, because past the as-of date the curve reads the invoices rather than the rule.", "The EAC and the variance at completion, since LOG-04 now forecasts its actual + commitment, and with them the projected Forecast; earned value, CPI, percent spent and SPI stay."]'::jsonb, 3, 'The published line with 70 spent and 60 committed on a budget of 100 forecasts 130.0000; commitments enter the rule and no other reading, and the curve projects whatever EAC the rule gives.'),
  ('portfolio', 'intermediate', 'final', null, 22, 'A reviewer estimates OFON-1''s time progress for 2027-06-30 by dividing the Jun 27 Planned point, 10748344, by the budget. The engine prints 0.493377. Why do the two disagree?', '["The engine counts five of the ten monthly points as passed and adds a share of June, so its fraction runs ahead of any single point on the curve drawn at that date.", "The engine counts 149 whole days elapsed since 2027-02-01 over the 302 days in the window, while the Jun 27 point samples the plan on the first of June.", "The engine measures time progress as the share of the 15090000 invoiced by the report date, a quantity the curve''s Planned line never uses at any of its points.", "The engine applies the CPI of 1.009377 to the calendar fraction before printing it, which lifts time progress above the ratio that the Planned line gives."]'::jsonb, 1, 'Time progress moves daily while points stand on the first of each month; 0.493377 of 27050000 is the planned value 13345861 that the SPI of 1.141290 divides by.'),
  ('portfolio', 'intermediate', 'final', null, 23, 'A drilling superintendent asks which OFON-1 line the SPI of 0.872063 as of 2027-08-15 says is running late. What can the SPI answer?', '["None: it is one ratio for the whole AFE, budget-weighted earned value over a straight plan, and it cannot name a line.", "CMP-05, since a line at 0.0000 percent is the only one that puts nothing into earned value while its whole budget sits in the plan.", "DRL-01, since the largest line carries most of the planned value and so alone decides whether the AFE reads below 1.", "Every line whose progress is under 0.645695 of its work, since SPI sets each line''s progress against the window''s time progress."]'::jsonb, 0, '15231500 over 17466060 weighs work by money and the calendar by money, and counts no days of delay on any line.'),
  ('portfolio', 'intermediate', 'final', null, 24, 'The published window from 2020-01-01 to 2020-12-31, read as of 2020-06-30, has one line with a budget of 1200, an actual of 200, a commitment of 100 and an entered forecast of 1500. Its last point reads Planned 1101 and Forecast 1377. What is the line''s EAC, and why is it not on the curve?', '["1377, because past the as-of date the Forecast series is the EAC itself, and the last point is where the projection finishes.", "1200, the budget, because an entered forecast is taken only when the actual + commitment of 300 has already passed the budget.", "1500, the entered forecast; the projection spreads it from the start and the last point stands on the first of December, so 1377 falls short of it as 1101 falls short of 1200.", "300, the actual + commitment, because the entered 1500 is set aside once invoices have been billed against the line."]'::jsonb, 2, 'A positive entered forecast wins, and on 12 monthly points the Forecast and the Planned lines take the same share of the calendar, of 1500 and of 1200.'),
  ('portfolio', 'intermediate', 'final', null, 25, 'Presenting OFON-1''s S-curve, a cost engineer explains the rise in Forecast from 15090000 at Aug 27 to 19374834 at Sep 27 as the commitments falling due in September. What does produce the rise?', '["The switch at the as-of date from invoiced spend to the EAC of 27600000 spread evenly from the window''s start, a projection that never starts from the actuals.", "The engineer is right: the curve adds the 5000000 committed to the last actual at the first point after the report''s date and spreads nothing else.", "The remaining budget projected at the AFE''s CPI of 1.009377 from the last actual of 15090000, which the curve adds on month by month until it reaches the end of the window.", "A spending surge expected in September from DRL-01''s remaining budget, which the forecast rule schedules into the first month after the report''s date because drilling is the largest line."]'::jsonb, 0, 'At Sep 27 the Forecast is the EAC''s share of the calendar, 19374834 against a Planned 18988742; its step from 15090000 measures how far the invoices sit from a straight line.'),
  ('portfolio', 'intermediate', 'final', null, 26, 'A new AFE is reported as of its start day. Progress is typed on its budgeted lines but no actuals have been entered. What CPI and SPI does the engine print?', '["CPI null and SPI null, because the repair made every division by zero across the AFE metrics return null in place of a number a chart could plot.", "CPI 1 and SPI 1, because a single guard returns 1 for both ratios whenever nothing has been spent on the lines and nothing has yet been planned.", "CPI 1 and SPI null: both ratios are undefined, but only the SPI says so, because CPI 1 whenever actuals are 0 is an unrepaired property.", "A refusal for the CPI, which the engine cannot compute without spend on the lines, and an SPI of 0 because no planned value has yet accrued."]'::jsonb, 2, 'The weighted earned value case shows CPI 1.000000 with 110.0000 earned and nothing spent, and OFON-1 on 2027-02-01 shows time progress 0.000000 and SPI null.'),
  ('portfolio', 'intermediate', 'final', null, 27, 'A published S-curve on a window from 2090-01-01 to 2091-01-01 has three lines: budget 1200 with actual 900 and commitment 600; budget 500 with forecast 650; budget 300 with forecast -10. Its last Forecast point is 2450. Which reading of the lines produces that figure?', '["The first line forecasts its budget of 1200 with its 600 committed added on top, the second its entered 650, and the third drops out because a negative entry removes the line.", "The rule before the repair, which took any non-zero entry: the first line at its actual + commitment, the second at 650 and the third at its entered -10.", "Every line forecasts its budget, 2000 in all, and the curve lifts the last point by the entered forecasts less the budgets they replace.", "The first line forecasts its actual + commitment of 1500, the second its entered 650, and the third its budget of 300, because -10 is not positive."]'::jsonb, 3, 'The 13 points reach the whole EAC because a point stands on the end date, where Planned is 2000; the third line''s -10 is ignored by the rule and by the curve.'),
  ('portfolio', 'intermediate', 'final', null, 28, 'A group capital summary adds OFON-1''s operator share of 6762500 to the risked EMV of 402.7500 on OKONO''s 600.0000 set. What is wrong with the sum?', '["Only the units: dividing 6762500 by a million and rounding to four decimals first makes the sum sound, since both figures are dollars of capital the operator stands behind.", "The two models share nothing: 6762500 is a share of an AFE budget in whole USD, 402.7500 a risked value in million USD, and no rescaling makes them one quantity.", "Only the timing: the operator''s share should be taken on the EAC of 27600000 rather than the budget, so that both figures describe the end of the programme and can be summed.", "Nothing, since an operator''s share and a risked EMV are both the operator''s expected outlay, and they add directly."]'::jsonb, 1, 'Mixing the two fields is the mistake examined here: 25.0000 percent of 27050000 is an authorised cost, and OKONO''s figure is value from a different inventory in a different unit.'),
  ('portfolio', 'intermediate', 'final', null, 29, 'OFON-1''s operator carries 25.0000 percent. A statement of costs incurred to date bills the operator 6762500. What went wrong?', '["Nothing, because a working interest is always billed on the authorised amount, and actual spend settles only when the AFE is closed.", "It billed the operator''s share of the 27050000 budget; the share of the 15090000 actually spent is 3772500.", "It billed on the EAC of 27600000, which carries the forecast overrun, where a statement of costs to date should bill the budget.", "It billed the operator on actuals plus the 5000000 committed, which a statement of costs to date leaves out until the orders are paid."]'::jsonb, 1, 'The split stays in the AFE''s currency: 25.0000 percent of 27050000 is 6762500, and 25.0000 percent of 15090000 is 3772500, the operator''s share of what has been spent.'),
  ('portfolio', 'intermediate', 'final', null, 30, 'Seeing 10224000 earned for 9800000 spent, DRL-01''s cost engineer enters a forecast between its 12400000 of actual + commitment and its 14200000 budget. What changes?', '["DRL-01 forecasts the entered figure, so the EAC and the projected Forecast fall and the line shows a saving the fallback could never show; CPI, SPI and earned value stay.", "Nothing, because the rule keeps the larger of an entered figure and the budget, so the line still forecasts 14200000.", "The EAC falls and CPI rises with it, since an entered forecast under the budget is read as cost performance on the line.", "Nothing yet, since an entry under the budget on an unfinished line is treated as not positive until the line reaches 100.0000 percent."]'::jsonb, 0, 'A positive entered forecast wins; without one DRL-01''s variance of 0 was the floor, and with one the variance at completion rises from -550000 by the line''s saving, while the progress-based readings never see the entry.'),
  ('portfolio', 'intermediate', 'final', null, 31, 'CSG-02 enters OFON-1''s EAC at 4300000 and its earned value at 3900000. Which figure is the engine''s error?', '["The earned value, because a line that is 100.0000 percent complete should earn what it actually cost, so the 4300000 spent on casing belongs in both of the readings.", "The EAC, because a finished line should forecast its budget of 3900000 once its typed progress reaches 100.0000 percent, and the extra spend belongs in the variance alone.", "Both, because the two readings should agree on a finished line, and the gap of 400000 between them shows a commitment counted twice after its order was paid.", "Neither: the forecast rule takes actual + commitment because it passes the budget, while earned value is budget times progress and never reads the actual."]'::jsonb, 3, 'Earned value pays each line what its work was authorised to cost, 3900000, which is exactly what lets it be set against the 4300000 spent; the rule forecasts what the line has cost.'),
  ('portfolio', 'intermediate', 'final', null, 32, 'Before the repair, an AFE whose window spanned today was opened on two days in a row with nothing changed on its lines. What differed between the two openings, and what does the repaired engine do instead?', '["The EAC, because the forecast rule read today''s date to decide which invoices counted toward each cost line, and the repaired rule reads the window''s end date in its place instead.", "The CPI, because actuals were pro-rated to today''s date across the window, and the repaired engine now reads the actuals as they stood on the window''s opening start date instead.", "The SPI, because the engine read the clock for time progress; it now takes an explicit as-of date, so OFON-1 run for 2027-08-15 gives planned value 17466060 whenever it is run.", "Nothing, since the old engine already took a report date, and the repair only renamed the field and added the refusal of an invalid one."]'::jsonb, 2, 'The same clock also walked the S-curve on to the current month, 81 points for a 2020 AFE on 2026-09-14; now the date is an input and the curve stops at the window''s end.'),
  ('portfolio', 'intermediate', 'final', null, 33, 'CMP-05 has 1200000 committed, nothing spent and progress of 0.0000. What does the line put into OFON-1''s readings?', '["Its 1200000 commitment into percent spent and its budget into earned value, since a line with orders placed is counted as started.", "Nothing into any reading, since a line at 0.0000 percent is left out of the AFE''s totals until its work begins.", "Nothing into earned value or percent spent, its 5600000 budget into the EAC, and the same budget into the plan that SPI divides by, which pulls SPI down.", "Its commitment into the EAC in place of its budget, because a committed line forecasts the money promised on it."]'::jsonb, 2, 'The fallback takes the larger of 5600000 and 1200000, and planned value of 17466060 is spread over all 27050000 of budget, including completion work that has not begun.'),
  ('portfolio', 'intermediate', 'final', null, 34, 'On OFON-1 as of 2027-08-15, suppose a line''s typed actual already includes an amount whose invoice is dated in September. Where does that money appear?', '["In both, since the curve reads the line actuals up to the as-of date and switches to the invoices only after it.", "In neither, since the engine holds a line''s actual back until the date of the invoice that supports it has been reached.", "On the curve only, which plots the invoice at Sep 27 as a projected actual, while the line''s actual waits for the next report.", "In percent spent and CPI, which read the line, and on no point of the Actual line, which is null past the as-of date."]'::jsonb, 3, 'The metrics read the line column and the curve the invoices, and the curve cuts an invoice dated after the as-of date; at Sep 27 its Actual is null while CPI still reads 1.009377.'),
  ('portfolio', 'intermediate', 'final', null, 35, 'OFON-1''s window is saved with its start date a month late by mistake, and nothing else changes. Which readings does the error reach?', '["Every reading, because earned value is pro-rated across the window and CPI then divides that pro-rated figure by the actuals.", "Time progress, planned value, SPI and the S-curve''s points and Planned line; the EAC, earned value, CPI, percent spent and percent complete are read from the lines and stay.", "Only the S-curve, because SPI takes its planned value from the budget and the as-of date, and never from the window.", "The EAC as well as SPI, because the forecast rule falls back to the budget only on lines whose window has already opened."]'::jsonb, 1, 'Planned value is the budget times the elapsed fraction of the window, 0.645695 of 27050000 at 2027-08-15 on the true dates, so only the calendar readings follow a wrong start.'),
  ('portfolio', 'intermediate', 'final', null, 36, 'Drawn as of 2027-06-30 rather than 2027-08-15, how many points does OFON-1''s S-curve carry, and why?', '["Still 10: the walk runs from the start date to the end date in monthly steps, and the as-of date decides only where Actual stops and Forecast projects.", "Fewer, since the repaired walk stops at the as-of date and plots no point after the day the report was run for.", "One more, since a report dated inside the window adds a point on the as-of date so that the plan behind the SPI can be read.", "As many as the months to the present, since the walk runs on from the start date to the current calendar month."]'::jsonb, 0, 'The repair bound the walk to the window, where before it a 2020 AFE drew 81 points on 2026-09-14; the as-of date moves null Actuals, never the count.'),
  ('portfolio', 'intermediate', 'final', null, 37, 'The published window from 2026-01-01 to 2027-12-31 returns SPI 1.139063 as of 2026-09-14 and SPI 0.940000 as of 2028-06-30. What is the second figure?', '["Earned value over the whole budget, the case''s percent complete divided by 100, because time progress stops at 1 after the end.", "A schedule ratio that has fallen because the plan kept growing after the end date while earned value stood still on the lines.", "The first reading corrected for the 256 of 729 days, applied once the window closed to turn a mid-window ratio into a final one.", "The case''s CPI, which the engine substitutes for SPI once the window has closed and planned value can no longer be computed."]'::jsonb, 0, 'At 2026-09-14 time progress is 0.351166, 256 of 729 days; after the end it is 1.000000, so the date can no longer move the 0.940000.'),
  ('portfolio', 'intermediate', 'final', null, 38, 'CMT-03''s engineer clears the entered forecast of 1400000, leaving the field blank. What happens to the line and to OFON-1?', '["CMT-03 forecasts its 940000 of actual + commitment, since a cleared field makes the rule forecast the money already out and promised.", "CMT-03 falls back to its budget of 1250000, the larger against 940000, so the variance at completion shrinks to CSG-02''s -400000 and the projected Forecast is drawn lower.", "Nothing, since a blank field keeps the last positive forecast the line held, and the EAC stays at 27600000.", "CMT-03 forecasts 0 and the variance at completion turns positive, because a blank forecast is read as a descope."]'::jsonb, 1, 'CMT-03''s -150000 existed only because it was typed; the spend overrun on CSG-02, -400000, stays because it rests on money already spent.'),
  ('portfolio', 'intermediate', 'final', null, 39, 'Which of these entries does the repaired AFE engine refuse outright with a message?', '["An entered forecast smaller than the money already spent and committed on the line, which the rule declines to take.", "An invoice whose date is null, which the curve refuses rather than place at an arbitrary day before the window.", "A progress figure below zero on a cost line, refused with a message that names the item.", "Progress above 100 percent, which the message says lies outside the range from 0 to 100 percent."]'::jsonb, 2, 'Negative progress fails with the item named, as the published message for CMP-02 at -20 percent shows; CMT-03 with 900000 entered is taken as typed, a null date counts from 1970, and progress past 100 percent is accepted, earning 150.0000 in its published case.'),
  ('portfolio', 'intermediate', 'final', null, 40, 'Past the as-of date the S-curve''s Forecast is the EAC spread from the window''s start. Could its first projected point sit below the last actual?', '["No, because the projection adds the spend still to come onto the last actual it follows, so the series can only rise or hold level past the as-of date.", "No, because the EAC is never below actual + commitment, so no share of it can fall under the invoices at any point.", "Only when an entered forecast is negative, since the S-curve takes a negative entry at its face value and pulls the projected line down under the actuals.", "Yes: the projection never starts from the actuals, so an AFE whose invoices ran ahead of a straight spread of its EAC would step down at the as-of date."]'::jsonb, 3, 'OFON-1 steps up from 15090000 to 19374834 because its invoices sit under the straight line; the size and sign of the step come from that distance, not from spending.'),
  ('portfolio', 'intermediate', 'final', null, 41, 'A partner asks how likely OFON-1''s variance at completion of -550000 is to hold. What can the AFE engine say?', '["Nothing about likelihood: variance at completion is one number from the forecast rule, with no range attached.", "That it is likely to hold, since a CPI of 1.009377 above 1 shows the lines buying work under budget, which caps any further overrun.", "That it is unlikely to grow, since the rule already forecasts every line at the larger of its budget and its actual + commitment.", "That it is likely on the drilling line, since DRL-01 at 72.0000 percent complete has the least work left in which to overrun."]'::jsonb, 0, 'CMP-05 has spent nothing and reports 0, exactly as DRL-01 does, so any overrun still to come on drilling, logging or completion is not in the -550000.'),
  ('portfolio', 'intermediate', 'final', null, 42, 'OFON-1''s Actual line sits above its Planned line at Mar 27, below it at Apr 27, above at May 27 and below at Jun 27. What do those swings say about the well?', '["That cost performance swung above and below 1 each month, since each crossing marks CPI passing through parity on the lines.", "Nothing: invoices arrive in lumps and the plan is a straight line in days, so each crossing is an invoice date meeting that line.", "That the schedule alternated between ahead and behind, because the Actual line is the earned value the SPI divides by.", "That drilling was front-loaded and then paused, which the engine''s plan reflects by phasing DRL-01''s budget into the early months of the window."]'::jsonb, 1, '3100000 sits above 2507947 at Mar 27 and below 5284603 at Apr 27 on the same money; CPI 1.009377 and earned value are on no point of the curve.');
