-- ============================================================================
-- EC5 PROFESSIONAL DEEP SEED: Capital Portfolio & Cost Control, intermediate
-- tier.
--
-- Six modules, 26 lessons, 132 questions (15 per module bank plus a 42
-- question final exam). The structure row is GENERATED from the tier's
-- manifest.json rather than hand typed.
--
-- What this tier owns: SPENDING AGAINST AN AFE. Lines, commitments and actuals;
-- one forecast rule and variance at completion; earned value, CPI and SPI; the
-- as-of date; the S-curve.
--
-- THE ENGINE FACT THIS TIER OWNS. EC5-0 gave the AFE engine an explicit as-of
-- date: planned value, time progress and SPI move with it, earned value, CPI
-- and EAC do not, and SPI is null where planned value is zero.
--
-- THE TRAP THE TIER IS BUILT ON. A forecast copied from the budget hides an
-- overrun, and an SPI read without a date is not a schedule measure.
-- ============================================================================

values ('portfolio', 'intermediate', '{"modules":[{"key":"m01-an-afe-is-a-promise","title":"An AFE Is a Promise","lesson_keys":["l01-authorisation-for-expenditure","l02-lines-budgets-and-commitments","l03-actuals-and-invoices","l04-the-currency-of-the-afe"]},{"key":"m02-one-forecast-rule","title":"One Forecast Rule","lesson_keys":["l01-an-entered-forecast","l02-budget-or-spend-plus-commitment","l03-a-forecast-that-is-not-positive","l04-variance-at-completion","l05-the-rule-the-screens-share"]},{"key":"m03-earned-value","title":"Earned Value","lesson_keys":["l01-progress-weighted-by-budget","l02-cost-performance","l03-planned-value-from-the-calendar","l04-schedule-performance","l05-percent-spent-and-percent-complete"]},{"key":"m04-the-as-of-date","title":"The As-of Date","lesson_keys":["l01-a-report-dated-once","l02-before-the-start","l03-inside-the-window","l04-after-the-end"]},{"key":"m05-the-s-curve","title":"The S-Curve","lesson_keys":["l01-monthly-buckets","l02-a-straight-plan","l03-actuals-from-invoices","l04-a-forecast-past-the-as-of-date","l05-a-curve-that-stops-at-the-end"]},{"key":"m06-the-professional-reading","title":"The Professional Reading","lesson_keys":["l01-the-story-so-far","l02-working-the-capstone","l03-onward"]}]}'::jsonb, 1)
on conflict (app_slug, tier) do update
  set structure = excluded.structure,
      content_version = excluded.content_version,
      active = true,
